namespace GlyphLens.Core.Abstractions;

/// <summary>
/// The application side of the worker pipe: it hosts the server end and accepts the worker as its single client.
/// </summary>
/// <remarks>
/// The pipe name is unique per session and generated by the listener, never supplied from outside. The Windows
/// implementation restricts the pipe to the current user and rejects network clients.
/// </remarks>
public interface IWorkerPipeListener : IDisposable
{
    /// <summary>The unique pipe name (not a full path), to be passed to the worker.</summary>
    string PipeName { get; }

    /// <summary>
    /// Waits for a client and returns the connected duplex stream. May be called again after the previous
    /// stream was disposed (for example after rejecting an unauthenticated client).
    /// </summary>
    ValueTask<Stream> AcceptAsync(CancellationToken cancellationToken);
}

public interface IWorkerPipeListenerFactory
{
    /// <summary>Creates a listener with a fresh unique pipe name; the pipe exists when this returns.</summary>
    IWorkerPipeListener Create();
}

/// <summary>What a worker needs to find and authenticate to the application.</summary>
/// <param name="PipeName">The pipe to connect to.</param>
/// <param name="SessionToken">A random per-session secret, passed to the worker out of band (not on the command line).</param>
public sealed record WorkerLaunchSpec(string PipeName, string SessionToken);

/// <summary>A running worker process.</summary>
public interface IWorkerProcess : IDisposable
{
    int Id { get; }

    /// <summary>Completes with the exit code when the process exits (also if it was killed).</summary>
    Task<int> Exited { get; }

    /// <summary>The last few lines the worker wrote to its error stream, sanitised and truncated.</summary>
    IReadOnlyList<string> RecentErrorOutput { get; }

    /// <summary>Terminates the process and anything it started. Safe to call after exit.</summary>
    void Kill();
}

/// <summary>Starts worker processes. Implementations tie the process's lifetime to the application's.</summary>
public interface IWorkerProcessLauncher
{
    /// <summary>Starts a worker. This can block briefly (interpreter discovery); call it off the UI thread.</summary>
    /// <exception cref="Models.WorkerException">The interpreter or worker could not be found, or the start failed.</exception>
    IWorkerProcess Launch(WorkerLaunchSpec spec);
}

/// <summary>One request/response observed on the worker connection. Never includes the payload.</summary>
public sealed record WorkerRequestLogEntry(string RequestId, string MessageType, TimeSpan Duration, string Outcome, string? ErrorCode = null);

/// <summary>Sink for worker diagnostics. Entries contain identifiers, durations and outcomes only, never message content.</summary>
public interface IWorkerLog
{
    void Request(WorkerRequestLogEntry entry);

    void Info(string message);
}

/// <summary>A log that discards everything.</summary>
public sealed class NullWorkerLog : IWorkerLog
{
    public static readonly NullWorkerLog Instance = new();

    public void Request(WorkerRequestLogEntry entry)
    {
    }

    public void Info(string message)
    {
    }
}
